import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Resizable from "../../ui/resizable";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  return Resizable.panelGroupView<Message>({
    direction: "vertical",
    className: "min-h-48",
    children: [
      Resizable.panelView<Message>({ size: 25, children: ["One"] }),
      Resizable.handleView<Message>({ direction: "vertical" }),
      Resizable.panelView<Message>({ size: 50, children: ["Two"] }),
      Resizable.handleView<Message>({ direction: "vertical" }),
      Resizable.panelView<Message>({ size: 25, children: ["Three"] }),
    ],
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Resizable Vertical example", () => {
  test("renders vertical panels and inert handles", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("One")).toHaveAttr("data-size", "25"),
      Scene.expect(Scene.text("Two")).toHaveAttr("data-size", "50"),
      Scene.expect(Scene.text("Three")).toHaveAttr("data-size", "25"),
      Scene.expect(
        Scene.role("separator", { name: "Resize panels" })
      ).toHaveAttr("aria-orientation", "vertical"),
      Scene.expect(
        Scene.role("separator", { name: "Resize panels" })
      ).not.toHaveHandler("pointerdown")
    );
  });
});
